import{c as a,Q as t,j as s,m as i}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"Self-Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"help/self-hosting.md","filePath":"help/self-hosting.md","lastUpdated":null}'),n={name:"help/self-hosting.md"};function l(o,e,h,r,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="self-hosting" tabindex="-1">Self-Hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-Hosting&quot;">​</a></h1><blockquote><p>This page is a compact entry point. The full, authoritative guide is <a href="https://github.com/Koushik0901/FinSight/blob/main/docs/self-hosting.md" target="_blank" rel="noreferrer"><code>docs/self-hosting.md</code></a> — read it top to bottom once, then return here for quick reference.</p></blockquote><p>FinSight runs on hardware you control as a single Docker image.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Koushik0901/FinSight.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FinSight</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> finsight</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → http://localhost:8674  (smoke test)</span></span></code></pre></div><p>First account → administrator; save the one-time recovery key.</p><h2 id="choosing-a-way-to-reach-it" tabindex="-1">Choosing a way to reach it <a class="header-anchor" href="#choosing-a-way-to-reach-it" aria-label="Permalink to &quot;Choosing a way to reach it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recipe</th><th>Domain</th><th>Certs</th><th>Who can reach it</th></tr></thead><tbody><tr><td><strong>A — Tailscale</strong> (recommended)</td><td><code>&lt;host&gt;.&lt;tailnet&gt;.ts.net</code></td><td>Tailscale manages Let’s Encrypt</td><td>Only devices on your tailnet — nothing on the public internet</td></tr><tr><td><strong>B — Caddy + public domain</strong></td><td><code>finsight.example.com</code></td><td>Caddy manages Let’s Encrypt</td><td>Anyone on the internet (login-protected)</td></tr><tr><td><strong>C — LAN + mkcert</strong></td><td><code>https://&lt;lan-name&gt;</code></td><td>mkcert local CA</td><td>Only devices that trust your CA, on your LAN</td></tr></tbody></table><p>All three give you a <strong>secure context</strong> (HTTPS) — required for the PWA, encrypted offline cache, and share-target.</p><h3 id="recipe-a-—-tailscale" tabindex="-1">Recipe A — Tailscale <a class="header-anchor" href="#recipe-a-—-tailscale" aria-label="Permalink to &quot;Recipe A — Tailscale&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8674</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → https://&lt;device&gt;.&lt;tailnet&gt;.ts.net</span></span></code></pre></div><p>Enable MagicDNS + HTTPS certificates in the Tailscale admin console. Keep <code>FINSIGHT_COOKIE_SECURE=1</code>.</p><h3 id="recipe-b-—-caddy" tabindex="-1">Recipe B — Caddy <a class="header-anchor" href="#recipe-b-—-caddy" aria-label="Permalink to &quot;Recipe B — Caddy&quot;">​</a></h3><p>Point DNS at your host, forward 80/443, then front the app:</p><p><code>Caddyfile</code>:</p><div class="language-caddyfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddyfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>finsight.example.com {</span></span>
<span class="line"><span>    reverse_proxy finsight:8674</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Drop <code>ports:</code> from <code>finsight</code> — only Caddy faces outward — and keep <code>FINSIGHT_COOKIE_SECURE=1</code>.</p><h3 id="recipe-c-—-mkcert-lan-only" tabindex="-1">Recipe C — mkcert (LAN-only) <a class="header-anchor" href="#recipe-c-—-mkcert-lan-only" aria-label="Permalink to &quot;Recipe C — mkcert (LAN-only)&quot;">​</a></h3><p>Generate a CA-trusted cert for a LAN hostname and front with Caddy/nginx. No VPN, no public port.</p><p>See the full guide for <code>mkcert</code> steps, brotli/Caddy notes, and PWA details.</p><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Pin <code>FINSIGHT_IMAGE</code> in <code>.env</code> to a release tag for reproducible upgrades. Back up <code>/data</code> first (whole volume, so <code>users.db</code> + <code>session.key</code> + every per-user DB stay together).</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><p>The authoritative reference — Tailscale serve flags, Caddy HTTP/2 reasoning, LAN TLS, backup/compose split examples, and operational limits — lives in <a href="https://github.com/Koushik0901/FinSight/blob/main/docs/self-hosting.md" target="_blank" rel="noreferrer"><code>docs/self-hosting.md</code></a>.</p><p>See also: <a href="/FinSight/getting-started/installation">Installation</a>, <a href="/FinSight/getting-started/first-launch">First Launch</a>, <a href="/FinSight/help/security">Security &amp; Privacy</a>.</p>`,26)])])}const k=a(n,[["render",l]]);export{g as __pageData,k as default};
